struct Decimal{bytes:[u8;20],start:usize}
impl Decimal{fn new(mut value:u64)->Self{let mut bytes=[0;20];let mut start=20;loop{start-=1;bytes[start]=b'0'+(value%10)as u8;value/=10;if value==0{break;}}Self{bytes,start}}fn as_str(&self)->&str{std::str::from_utf8(&self.bytes[self.start..]).expect("decimal bytes are ASCII")}}
